import queue

class Solve:

    def __init__(self) -> None:
        self.x = 0;
        self.dem = 0;

    def vao(self) -> None:
        self.x = abs(int(input()));

    def lam(self) -> None:
        tong = 0;
        # Vòng while lặp đến khi tìm được số có hiệu của số đó với x chia hết cho 2
        # Biến tổng được tính bằng cách cộng các chỉ số của mỗi bước nhảy tiến cho đến khi thỏa mãn điều kiện
        # Vậy khi thay 1 bước nhảy bất kỳ thành lùi thì tổng sẽ giảm đi một lượng là 2 * chỉ số của bước nhảy tương ứng
        while(tong < self.x or (tong - self.x) % 2 != 0):
            self.dem += 1;
            tong += self.dem;

    def ra(self) -> None:
        print(self.dem);


def main():
    p = Solve();
    p.vao();
    p.lam();
    p.ra();

main();

"""
Jack is working on his jumping skills recently. Currently he's located at point zero of the number line. He would like to get to the point x. In order to train, he has decided that he'll first jump by only one unit, and each subsequent jump will be exactly one longer than the previous one. He can go either left or right with each jump. He wonders how many jumps he needs to reach x.

Input
The input data consists of only one integer x ( - 109 ≤ x ≤ 109).

Output
Output the minimal number of jumps that Jack requires to reach x.
"""
from math import *

def is_even(a):
    return False if a%2 else True

def calc_sum(n):
    return n * (n + 1)/2

def check(a, x):
    return (not is_even(a) and not is_even(x)) or (is_even(a) and is_even(x))

x = abs(int(input()))

if x == 0:
    print(0)
else:
    n = (-1+pow(1+4*2*x, 0.5))/2

    ceil_n = ceil(n)

    if check(calc_sum(ceil_n), x):
        print(ceil_n)
    else:
        if check(calc_sum(ceil_n + 1), x):
            print(ceil_n + 1)
        else:
            print(ceil_n + 2)

x = abs(int(input()))
n = 0
total = 0
while total < x:
    n += 1
    total += n

diff = total - x
if diff % 2 == 0:
    print(n)
else:
    if n % 2 == 0:
        print(n + 1)
    else:
        print(n + 2)

def Solve(n):
    a = -1
    b = 1000000000
    while b - a > 1:
        e = (b + a) // 2
        s = (e * (e + 1)) // 2
        if s >= n:
            b = e
        else:
            a = e
    total = (b * (b + 1)) // 2
    diff = total - n
    if diff % 2 == 0:
        return b
    elif (diff + b + 1) % 2 == 0:
        return b + 1
    else:
        return b + 2


x = int(input())
x = abs(x)
print(Solve(x))

