class Solve:
    def __init__(self):
        self.x = 0
        self.dem = 0

    def vao(self):
        self.x = int(input())

    def lam(self):
        x = abs(self.x)
        tong = 0
        i = 1

        while tong < x or (tong - x) % 2 != 0:
            tong += i
            self.dem += 1
            i += 1

    def ra(self):
        print(self.dem)


