import math

a = abs(int(input()))

if a == 0:
    print(0)
else:
    n = math.ceil((math.sqrt(1 + 8 * a) - 1) / 2)
    while (n * (n + 1)) // 2 < a or ((n * (n + 1)) // 2 - a) % 2 != 0:
        n += 1
    print(n)

def numberOfJumps(n):
    n = abs(n)
    j = 0
    while True:
        s = j * (j + 1) // 2
        if s >= n and (s - n) % 2 == 0:
            return j
        j += 1


x = int(input())
print(numberOfJumps(x))

